// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.system.handlerimport timber.log.Timberimport com.roshan.persona.brain.skill.SystemOperationimport com.roshan.persona.common.AppErrorimport com.roshan.persona.common.CorrelationIdimport com.roshan.persona.common.Resultimport com.roshan.persona.system.executor.ResourceCategory/** * NOUS — Wi-Fi Handler (Module 10 v2 — Step 10.5). * * Toggles Wi-Fi on/off. Implements graceful degradation per Android API * level (Review 2 Fix C — exception handling + Review 1 strategy §10.6). * * ## API level behavior (per strategy §"Privacy & Security") * *  - **API 28 and below**: `WifiManager.setWifiEnabled` works directly. *    Requires `CHANGE_WIFI_STATE` permission. Synchronous toggle. * *  - **API 29+ (Android 10+)**: Google blocked programmatic Wi-Fi toggle *    for non-system apps. The handler **opens `Settings.Panel.ACTION_WIFI`** — *    an inline panel where the user can toggle manually. This is the *    official Android UX for this action. * * ## Idempotent execution (Review 2 Elite 1) * * If Wi-Fi is already in the target state, skip the hardware call. This * avoids redundant Settings.Panel prompts on API 29+ (which would be * annoying — every "Wi-Fi on" command would open the panel even if Wi-Fi * is already on). * * ## Pre-state capture (Review 2 Fix A) * * Captures the previous on/off state. Undo restores the actual previous * state — not the inverse. * * ## Reversibility caveat (API 29+) * * On API 29+, undo can't programmatically re-toggle (the user toggled * manually in the panel). The handler records the pre-state anyway — if * the user manually set Wi-Fi off and then says "undo", NOUS opens the * panel again with a hint: "Wi-Fi was on — toggle it back?" * * ## Resource category * * Wi-Fi uses [ResourceCategory.CONNECTIVITY] — multiple connectivity ops * in a batch run sequentially to avoid radio contention. * * @see <a href="docs/strategy/module-10-system-strategy-v2.md">§Privacy & Security — Connectivity</a> */class WifiHandler(    private val wifiService: WifiService,) : ReversibleHandler<SystemOperation.SetWifi> {    override val id: String = "wifi"    override val displayName: String = "Wi-Fi Control"    override val requiredPermissions: Set<String> = setOf(        android.Manifest.permission.ACCESS_WIFI_STATE,        android.Manifest.permission.CHANGE_WIFI_STATE,    )    override val resourceCategory: ResourceCategory = ResourceCategory.CONNECTIVITY    override fun isAvailable(): Boolean = wifiService.isAvailable()    override suspend fun execute(operation: SystemOperation.SetWifi): Result<Unit> {        if (!isAvailable()) {            return Result.Failure(                error = AppError.Hardware.Unavailable("wifi"),                correlationId = CorrelationId.generate(),                durationNanos = 0,            )        }        return try {            if (wifiService.canToggleDirectly()) {                // API 28- — direct toggle.                val success = wifiService.setEnabled(operation.on)                if (success) {                    Result.Success(Unit, CorrelationId.generate(), 0)                } else {                    Result.Failure(                        error = AppError.Hardware.Unknown("wifi"),                        correlationId = CorrelationId.generate(),                        durationNanos = 0,                    )                }            } else {                // API 29+ — open Settings.Panel.                val launched = wifiService.openSettingsPanel()                if (launched) {                    Result.Success(                        data = Unit,                        correlationId = CorrelationId.generate(),                        durationNanos = 0,                        warnings = listOf("opened_settings_panel"),                    )                } else {                    Result.Failure(                        error = AppError.Hardware.Unsupported("wifi_panel"),                        correlationId = CorrelationId.generate(),                        durationNanos = 0,                    )                }            }        } catch (t: Throwable) {            Timber.tag("WifiHandler").w("execute failed", t)            Result.Failure(                error = AppError.Hardware.Unknown("wifi", t),                correlationId = CorrelationId.generate(),                durationNanos = 0,            )        }    }    override suspend fun capturePreState(operation: SystemOperation.SetWifi): Any? {        return try {            WifiPreState(wasEnabled = wifiService.isEnabled())        } catch (t: Throwable) {            Timber.tag("WifiHandler").w("capturePreState failed", t)            null        }    }    override suspend fun restorePreState(operation: SystemOperation.SetWifi, preState: Any?) {        if (preState !is WifiPreState) return        try {            if (wifiService.canToggleDirectly()) {                wifiService.setEnabled(preState.wasEnabled)            } else {                // API 29+ — can't toggle directly. Open the panel + log a hint.                Timber.tag("WifiHandler").i("Undo: Wi-Fi was ${if (preState.wasEnabled) "on" else "off"} — opening panel for manual restore.")                wifiService.openSettingsPanel()            }        } catch (t: Throwable) {            Timber.tag("WifiHandler").w("restorePreState failed", t)        }    }    override suspend fun getCurrentState(): Any? = try {        WifiPreState(wasEnabled = wifiService.isEnabled())    } catch (t: Throwable) { null }    override suspend fun isAlreadyInTargetState(operation: SystemOperation.SetWifi): Boolean {        return try {            wifiService.isEnabled() == operation.on        } catch (t: Throwable) {            false        }    }    override fun describeOperation(operation: SystemOperation.SetWifi): String =        if (operation.on) "Wi-Fi turned on" else "Wi-Fi turned off"    // ─── Pre-state serialization (audit defect B fix) ─────────────────────    override fun serializePreState(preState: Any?): String? {        if (preState == null) return null        if (preState !is WifiPreState) {            return com.roshan.persona.system.undo.SystemOperationSerializer.serializePreState(preState)        }        return "{\"type\":\"WifiPreState\",\"wasEnabled\":${preState.wasEnabled}}"    }    override fun deserializePreState(json: String?): Any? {        if (json == null) return null        val map = try {            com.roshan.persona.system.undo.SystemOperationSerializer.parseJsonObject(json)        } catch (t: Throwable) {            return com.roshan.persona.system.undo.SystemOperationSerializer.deserializePreState(json)        }        return when (map["type"] as? String) {            "WifiPreState" -> WifiPreState(wasEnabled = (map["wasEnabled"] as? Boolean) ?: false)            else -> com.roshan.persona.system.undo.SystemOperationSerializer.deserializePreState(json)        }    }    /** Captured pre-state for Wi-Fi (previous on/off). */    data class WifiPreState(val wasEnabled: Boolean)}
